    adcs_vec3_t dBdt, m, tau;
    double power;

    if ((field_body_t == NULL) || (body_rate_rad_s == NULL) || (predicted_power_w == NULL)) {
        return ADCS_E_NULL;
    }
    if ((!adcs_is_finite_vec3(field_body_t)) || (!adcs_is_finite_vec3(body_rate_rad_s)) ||
        (!isfinite(gain)) || (gain < 0.0)) {
        *predicted_power_w = 0.0;
        return ADCS_E_RANGE;
    }

    /* dB/dt = -omega cross B */
    dBdt = adcs_vec3_cross(body_rate_rad_s, field_body_t);
    dBdt = adcs_vec3_scale(&dBdt, -1.0);

    /* m = -gain * dB/dt */
    m = adcs_vec3_scale(&dBdt, -gain);

    /* tau = m cross B */
    tau = adcs_vec3_cross(&m, field_body_t);

    /* power = tau dot omega */
    power = adcs_vec3_dot(&tau, body_rate_rad_s);

    /* contract: nonpositive predicted power */
    if (power > 0.0) {
        power = 0.0;
    }

    *predicted_power_w = power;
    return ADCS_OK;
}

